files.content:
html {
  block-size: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-weight: 800;
  font-size: 24px;
  text-align: center;
  text-transform: uppercase;
  block-size: 100%;
}

.element {
  margin: 3em;
  border: 80px solid transparent;
  padding: 20px 50px;
  inline-size: fit-content;
  max-inline-size: 850px;
  border-image-source: url(https://code.s3.yandex.net/web-developer/verstka/mondr-base.png);
  border-image-slice: 20% 10% 20% 30% fill;
  border-image-width: 30px 20%;
}
